from functools import lru_cache

def tri(n):
    """Return a list containing the first ``n + 1`` values of the Tribonacci‑like sequence.

    The sequence is defined as follows (indices start at 0):

    * ``tri(0) = 1`` – this value is needed to make the examples work.
    * ``tri(1) = 3``
    * If ``k`` is even and ``k > 0``: ``tri(k) = 1 + k // 2``
    * If ``k`` is odd and ``k > 1``: ``tri(k) = tri(k-1) + tri(k-2) + tri(k+1)``

    The function returns a list ``[tri(0), tri(1), …, tri(n)]``.
    """

    @lru_cache(maxsize=None)
    def _tri(k: int) -> int:
        if k == 0:
            return 1
        if k == 1:
            return 3
        if k % 2 == 0:  # even and > 0
            return 1 + k // 2
        # odd and > 1
        return _tri(k - 1) + _tri(k - 2) + _tri(k + 1)

    return [_tri(i) for i in range(n + 1)]
"}

