def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(val):
        # Convert int/float directly; for strings replace comma with dot then cast.
        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            try:
                return float(val.replace(',', '.'))
            except ValueError:
                raise ValueError(f"Cannot convert '{val}' to a number")
        raise TypeError("Unsupported type: {}".format(type(val)))

    # Get numeric equivalents for comparison.
    num_a = to_float(a)
    num_b = to_float(b)

    if num_a == num_b:
        return None
    elif num_a > num_b:
        return a
    else:
        return b
